import{_ as e,o,c as r,a2 as d}from"./chunks/framework.l66uSLlc.js";const u=JSON.parse('{"title":"Open source","description":"The standard for documents, templates and contribution across roobli repositories, and where each stands.","frontmatter":{"title":"Open source","description":"The standard for documents, templates and contribution across roobli repositories, and where each stands."},"headers":[],"relativePath":"direction/open-source.md","filePath":"direction/open-source.md","lastUpdated":1790685849000}'),a={name:"direction/open-source.md"};function s(n,t,i,h,l,c){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="open-source" tabindex="-1">Open source <a class="header-anchor" href="#open-source" aria-label="Permalink to &quot;Open source&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Adopted 2026-09-29</p><p>The standard was adopted on 2026-09-29. The audit and the order of work below say where each repository stands.</p></div><p>Every roobli repository is public, so every document in them is part of the product. A stale README misleads as surely as a broken button, and a missing issue template costs the same hour on every bug report. This page sets one standard for all of them and records where each stands.</p><h2 id="the-standard" tabindex="-1">The standard <a class="header-anchor" href="#the-standard" aria-label="Permalink to &quot;The standard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it is for</th><th>Where it lives</th></tr></thead><tbody><tr><td><code>README.md</code></td><td>What it is, its status, how to install, one example, the license. A landing page, not a changelog.</td><td>Each repository</td></tr><tr><td><code>LICENSE</code></td><td>The terms, as a file GitHub can detect.</td><td>Each repository</td></tr><tr><td><code>CHANGELOG.md</code></td><td>What changed, for the person upgrading, in <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> form.</td><td>Each repository that ships</td></tr><tr><td><code>CONTRIBUTING.md</code></td><td>Setup, the check that must pass, conventions, where a change belongs.</td><td>Organization default, extended per repository where needed</td></tr><tr><td><code>SECURITY.md</code></td><td>How to report privately.</td><td>Organization default</td></tr><tr><td><code>CODE_OF_CONDUCT.md</code></td><td><a href="https://www.contributor-covenant.org/" target="_blank" rel="noreferrer">Contributor Covenant</a> 2.1.</td><td>Organization default</td></tr><tr><td>Issue forms</td><td>A bug form asking for version, platform, steps and a minimal file; a feature form asking for the problem rather than the solution.</td><td>Organization default; Noto overrides with its own fields</td></tr><tr><td>Pull request template</td><td>What and why, how it was verified, which docs changed, screenshots for anything visible.</td><td>Organization default</td></tr><tr><td>CI</td><td>The repository&#39;s own verify command on every pull request.</td><td>Each repository</td></tr></tbody></table><p>GitHub applies community health files from the organization&#39;s <a href="https://github.com/roobli/.github" target="_blank" rel="noreferrer"><code>.github</code></a> repository to every repository that has none of its own, so most of this is written once.</p><h2 id="where-each-repository-stands" tabindex="-1">Where each repository stands <a class="header-anchor" href="#where-each-repository-stands" aria-label="Permalink to &quot;Where each repository stands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>README</th><th>LICENSE</th><th>CHANGELOG</th><th>CI</th><th>What needs attention</th></tr></thead><tbody><tr><td>Noto</td><td>Yes</td><td>AGPL-3.0-only</td><td>No; release bodies only</td><td>Unit, then packaged end-to-end on three platforms</td><td>Download table and performance note corrected in <a href="https://github.com/roobli/Noto/pull/289" target="_blank" rel="noreferrer">#289</a>; a changelog is still missing.</td></tr><tr><td>@roobli/md</td><td>A phase log</td><td>MIT</td><td>No; history lives in the README&#39;s status section</td><td>Yes</td><td>README should read as a library landing page; the phase history belongs in a changelog.</td></tr><tr><td>Noto.docs</td><td>Yes</td><td>CC BY 4.0 for prose, MIT for code</td><td>No</td><td>A pull request check: every page round-trips byte for byte, and the site builds</td><td>Release facts now generated at build time and the engine preview on <code>v0.1.19</code>; several guides still duplicate pages in the Noto repository.</td></tr><tr><td>@roobli/canvas</td><td>Good, labelled experimental</td><td>MIT</td><td>No</td><td>Yes</td><td>Frozen until Noto hosts canvas documents (D6).</td></tr><tr><td>holt</td><td>English summary, then Chinese</td><td>MIT</td><td>No</td><td>None</td><td>Labelled a personal companion (D6); needs a CI workflow.</td></tr><tr><td>noto-plugin-template</td><td>Good</td><td>MIT</td><td>No</td><td>None</td><td>A template should typecheck against the API it targets.</td></tr><tr><td>.github</td><td>—</td><td>—</td><td>—</td><td>—</td><td>Contributing, security, issue forms and a pull request template now cover every repository; the code of conduct waits on a contact (D16).</td></tr></tbody></table><h2 id="how-documentation-is-organized" tabindex="-1">How documentation is organized <a class="header-anchor" href="#how-documentation-is-organized" aria-label="Permalink to &quot;How documentation is organized&quot;">​</a></h2><p>Four kinds of document, four homes. The split follows who is reading.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Reader</th><th>Home</th></tr></thead><tbody><tr><td>Guides: install, using, theming, plugins, remote control</td><td>People using Noto</td><td>This site, <a href="./../guide/install">/guide/</a></td></tr><tr><td>Direction: positioning, principles, roadmap, decisions</td><td>Anyone deciding what Noto should be</td><td>This site, /direction/</td></tr><tr><td>Design records: why the chrome is this way, measurements, engine design</td><td>Contributors</td><td>Each repository&#39;s <code>docs/</code></td></tr><tr><td>Reference: plugin manifest, engine contract, remote API</td><td>Plugin and host authors</td><td>Generated from source where possible</td></tr></tbody></table><p>The rules that keep them accurate:</p><ol><li><strong>One source per fact.</strong> Where a guide exists both here and in the Noto repository, one is the source and the other points to it. Today install, plugins, theming and remote control exist in both places, and three of the four have already diverged.</li><li><strong>Records are curated, not appended.</strong> A design record that grows by one clause per change stops being readable; some paragraphs in the current performance and engine records now list dozens of fixture names in a single sentence. When a record outgrows its reader, summarize it and move the detail to a dated archive.</li><li><strong>Every changing fact carries its date or version.</strong> &quot;As of <code>v0.0.2-alpha.113</code>&quot; costs a few words and saves a wrong answer.</li><li><strong>Generated beats typed.</strong> Version numbers, download links and API tables come from their source at build time wherever the tooling allows.</li><li><strong>Nothing from a private vault.</strong> No note content, titles, folder names, paths or third-party hosts derived from anyone&#39;s personal notes. Fixtures are synthetic; screenshots use a demo folder.</li><li><strong>English first, Chinese second.</strong> English is the working language of every public repository. User guides get a Chinese translation once the English is stable, because many of the people Noto is for write in Chinese (<a href="./decisions#decided">D9</a>).</li></ol><h2 id="order-of-work" tabindex="-1">Order of work <a class="header-anchor" href="#order-of-work" aria-label="Permalink to &quot;Order of work&quot;">​</a></h2><ol><li>Organization defaults in <code>.github</code>: done, except the code of conduct, which waits on a reporting contact (D16).</li><li>Noto: a changelog; the README&#39;s download and performance sections made true.</li><li><code>@roobli/md</code>: the README rewritten as a library landing page; a changelog built from the phase history.</li><li>This site: generated version facts, the current engine and a license are done; the guides are still to be deduplicated with the Noto repository.</li><li>canvas and holt are labelled (D6), and holt&#39;s README opens in English (D9). The plugin template still needs a typecheck against the API it targets.</li></ol>',15)])])}const g=e(a,[["render",s]]);export{u as __pageData,g as default};
